    for (var i = 0; i < runs.length; i++) {
        var r = runs[i] || {};
        var s = r.status ? String(r.status).toLowerCase() : '';
        if (s !== 'queued' && s !== 'in_progress' && s !== 'waiting' && s !== 'pending') continue;
