                say('🔁 deferred approved → SM tick dispatched (self-heal)');
            } catch (eTick) {
                say('⚠️ self-tick dispatch failed: ' + ((eTick && eTick.message) || eTick));
            }
        }
    }

    say('mergeBot complete — acted: ' + acted);
    return { success: true, acted: acted, log: log };
}

